// ProductCard.js
import React from 'react';
import PropTypes from 'prop-types';
import { useHistory } from 'react-router-dom';
import './ProductCard.css';

const ProductCard = ({
  title,
  image,
  onContact,
  id,
  type,
  externalUrl,
}) => {
  const history = useHistory();
  const handleCardClick = (e) => {
    // Prevent button click from triggering card navigation
    if (e.target.closest('button')) return;
    // If this is an external/etsy product, open the external URL instead of navigating internally
    if (type === 'etsy' && externalUrl) {
      window.open(externalUrl, '_blank', 'noopener,noreferrer');
      return;
    }
    history.push(`/product/${id}`);
  };
  return (
    <div className='product-card' onClick={handleCardClick} style={{ cursor: 'pointer' }}>
      <img className='product-image' src={image} alt={title} />
      <h3 className='product-title'>{title}</h3>
      {type === 'etsy' && externalUrl && (
        <button
          className='etsy-btn'
          onClick={(e) => {
            // prevent the card handler from also firing
            e.stopPropagation();
            window.open(externalUrl, '_blank', 'noopener,noreferrer');
          }}
        >
          See on Etsy
        </button>
      )}
      {type !== 'etsy' && (
        <button className='contact-btn' onClick={(e) => { e.stopPropagation(); onContact(); }}>Contact Me</button>
      )}
    </div>
  );
};

ProductCard.propTypes = {
  title: PropTypes.string.isRequired,
  image: PropTypes.string.isRequired,
  onContact: PropTypes.func.isRequired,
  id: PropTypes.oneOfType([PropTypes.string, PropTypes.number]).isRequired,
  type: PropTypes.string,
  externalUrl: PropTypes.string,
};

export default ProductCard;
